@Component("interview-handler")
@ProcessingGroup("interview-processing-group")
public class InterviewEventHandler {
	
	// core constructor
	InterviewEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateInterviewEvent
     */
    @EventHandler
    public void handle( CreateInterviewEvent event) {
        entityManager.persist(new Interview(event.getInterviewId(), event.getInterviewDate(), event.getFeedback(), event.getRequisition(), event.getCandidate(), event.getInterviewers(), event.getStage(), event.getResult()));
    }

    /*
     * @param	event UpdateInterviewEvent
     */
    @EventHandler
    public Interview handle( UpdateInterviewEvent event) {
    	entityManager.merge(new Interview(event.getInterviewId(), event.getInterviewDate(), event.getFeedback(), event.getRequisition(), event.getCandidate(), event.getInterviewers(), event.getStage(), event.getResult()));
    }
    
    /*
     * @param	event DeleteInterviewEvent
     */
    @EventHandler
    public void on( DeleteInterviewEvent event) {
    	Interview entity = new Interview();
   
    	// ------------------------------------------
    	// apply the InterviewId
    	// ------------------------------------------
    	entity.setInterviewId( event.getInterviewId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final InterviewRepository interviewEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(InterviewEventHandler.class.getName());

}
